        // given
        given(productRepository.findAllByProductNumberIn(any()))
                .willReturn(List.of(createProduct("001", 4000)));
        given(stockRepository.findAllByProductNumberIn(any()))
                .willReturn(List.of());
        given(orderRepository.save(any())).willReturn(mock(Order.class));

